import math

def carburising_time(depth, C0, Cs, C_case, D):
    y = (Cs - C_case) / (Cs - C0)
    if not 0 < y < 1:
        raise ValueError("C_case must lie strictly between C0 and Cs")
    lo, hi = 0.0, 6.0
    for _ in range(100):
        mid = (lo + hi) / 2
        if math.erf(mid) < y:
            lo = mid
        else:
            hi = mid
    z = (lo + hi) / 2
    return (depth / (2 * z)) ** 2 / D
